package workspace

// clio's TemplateProvider over the templates it ships in tpl/, embedded here as one zip generated by
// scripts/generate-workspace-templates.py (manifest.json lists every file with its SHA-256 and mode).

import (
	"archive/zip"
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
)

//go:embed templates/templates.zip
var templatesZip []byte

//go:embed templates/manifest.json
var templatesManifest []byte

type templateFile struct {
	path string // relative to tpl/, forward slashes
	data []byte
	mode os.FileMode
}

var loadTemplates = sync.OnceValues(func() (map[string]templateFile, error) {
	var manifest struct {
		Files []struct {
			Path   string `json:"path"`
			Size   int    `json:"size"`
			SHA256 string `json:"sha256"`
			Mode   string `json:"mode"`
		} `json:"files"`
	}
	if err := json.Unmarshal(templatesManifest, &manifest); err != nil {
		return nil, fmt.Errorf("template manifest: %w", err)
	}
	reader, err := zip.NewReader(bytes.NewReader(templatesZip), int64(len(templatesZip)))
	if err != nil {
		return nil, fmt.Errorf("template archive: %w", err)
	}
	entries := map[string]*zip.File{}
	for _, entry := range reader.File {
		entries[entry.Name] = entry
	}
	files := map[string]templateFile{}
	for _, item := range manifest.Files {
		entry, ok := entries[item.Path]
		if !ok {
			return nil, fmt.Errorf("template archive has no %s", item.Path)
		}
		stream, err := entry.Open()
		if err != nil {
			return nil, err
		}
		data, err := io.ReadAll(stream)
		stream.Close()
		if err != nil {
			return nil, err
		}
		digest := sha256.Sum256(data)
		if len(data) != item.Size || hex.EncodeToString(digest[:]) != item.SHA256 {
			return nil, fmt.Errorf("template %s does not match its manifest", item.Path)
		}
		mode, err := strconv.ParseUint(item.Mode, 8, 32)
		if err != nil {
			return nil, fmt.Errorf("template %s mode: %w", item.Path, err)
		}
		files[item.Path] = templateFile{path: item.Path, data: data, mode: os.FileMode(mode)}
	}
	return files, nil
})

// templatesUnder lists the files of one template folder, sorted by path.
func templatesUnder(folder string) ([]templateFile, error) {
	files, err := loadTemplates()
	if err != nil {
		return nil, err
	}
	prefix := strings.TrimSuffix(filepath.ToSlash(folder), "/") + "/"
	var found []templateFile
	for name, file := range files {
		if strings.HasPrefix(name, prefix) {
			found = append(found, file)
		}
	}
	if len(found) == 0 {
		return nil, fmt.Errorf("Could not find a part of the path '%s'.", folder)
	}
	sort.Slice(found, func(i, j int) bool { return found[i].path < found[j].path })
	return found, nil
}

// template is TemplateProvider.GetTemplate: tpl/<name>.tpl when it exists, else tpl/<name>.
func template(name string) (string, error) {
	files, err := loadTemplates()
	if err != nil {
		return "", err
	}
	name = filepath.ToSlash(name)
	if file, ok := files[name+".tpl"]; ok {
		return string(bytes.TrimPrefix(file.data, []byte{0xEF, 0xBB, 0xBF})), nil
	}
	if file, ok := files[name]; ok {
		return string(bytes.TrimPrefix(file.data, []byte{0xEF, 0xBB, 0xBF})), nil
	}
	return "", fmt.Errorf("Invalid template file path '%s'", name)
}

// templateDirectories is TemplateProvider.GetTemplateDirectories: the names of the folders directly under
// a template folder.
func templateDirectories(folder string) ([]string, error) {
	files, err := templatesUnder(folder)
	if err != nil {
		return nil, err
	}
	prefix := strings.TrimSuffix(filepath.ToSlash(folder), "/") + "/"
	seen := map[string]bool{}
	var names []string
	for _, file := range files {
		rest := strings.TrimPrefix(file.path, prefix)
		if slash := strings.Index(rest, "/"); slash > 0 && !seen[rest[:slash]] {
			seen[rest[:slash]] = true
			names = append(names, rest[:slash])
		}
	}
	return names, nil
}

// copyTemplateFolder is TemplateProvider.CopyTemplateFolder(name, destination, "", "", overwrite) over
// FileSystem.CopyDirectory: the destination is created, or emptied first when it exists and overwrite is
// set, and every file is copied over whatever is there, keeping the template's mode (File.Copy on Unix).
func copyTemplateFolder(folder, destination string, overwrite bool) error {
	files, err := templatesUnder(folder)
	if err != nil {
		return err
	}
	if directoryExists(destination) {
		if overwrite {
			if err := clearDirectory(destination); err != nil {
				return err
			}
		}
	} else if err := os.MkdirAll(destination, 0o777); err != nil {
		return err
	}
	prefix := strings.TrimSuffix(filepath.ToSlash(folder), "/") + "/"
	for _, file := range files {
		target := filepath.Join(destination, filepath.FromSlash(strings.TrimPrefix(file.path, prefix)))
		if err := os.MkdirAll(filepath.Dir(target), 0o777); err != nil {
			return err
		}
		if err := copyTemplateFile(file, target); err != nil {
			return err
		}
	}
	return nil
}

func copyTemplateFile(file templateFile, target string) error {
	if err := os.WriteFile(target, file.data, file.mode); err != nil {
		return err
	}
	if runtime.GOOS == "windows" {
		return nil
	}
	return os.Chmod(target, file.mode)
}

// clearDirectory is FileSystem.ClearDirectory: every file and folder inside is removed.
func clearDirectory(directory string) error {
	entries, err := os.ReadDir(directory)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if err := os.RemoveAll(filepath.Join(directory, entry.Name())); err != nil {
			return err
		}
	}
	return nil
}

// copyTemplateFolderWithMacros is TemplateProvider.CopyTemplateFolder(name, destination, macros): only the
// *.tpl files, read as text, every macro replaced in order in the text and in the target path, ".tpl"
// removed from the path, written as new UTF-8 text.
func copyTemplateFolderWithMacros(folder, destination string, macros [][2]string) error {
	files, err := templatesUnder(folder)
	if err != nil {
		return err
	}
	prefix := strings.TrimSuffix(filepath.ToSlash(folder), "/") + "/"
	for _, file := range files {
		if path.Ext(file.path) != ".tpl" {
			continue
		}
		content := replaceMacros(string(bytes.TrimPrefix(file.data, []byte{0xEF, 0xBB, 0xBF})), macros)
		relative := filepath.FromSlash(strings.TrimPrefix(file.path, prefix))
		target := strings.ReplaceAll(filepath.Join(destination, relative), ".tpl", "")
		target = replaceMacros(target, macros)
		if err := os.MkdirAll(filepath.Dir(target), 0o777); err != nil {
			return err
		}
		if err := writeAllText(target, content); err != nil {
			return err
		}
	}
	return nil
}

func replaceMacros(text string, macros [][2]string) string {
	for _, macro := range macros {
		text = strings.ReplaceAll(text, macro[0], macro[1])
	}
	return text
}
